// Install these packages before running:
//   npm install react react-dom carbon-components carbon-components-react

import React, { useState } from 'react';
import { render } from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { Dropdown } from 'carbon-components-react';

function App() {
  const items = [
    { id: 'option-0', text: 'Option 0' },
    { id: 'option-1', text: 'Option 1' },
    { id: 'option-2', text: 'Option 2' },
    { id: 'option-3', text: 'Option 3' },
  ];

  // Force the dropdown menu to stay open on mount:
  const [isOpen, setIsOpen] = useState(true);

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Dropdown Accessibility Violation Demo</h2>
      <Dropdown
        id="demo-dropdown"
        label="Dropdown menu options"
        items={items}
        itemToString={(item) => (item ? item.text : '')}
        downshiftProps={{
          // isOpen will keep the list open so you can immediately run your accessibility scan
          isOpen,
          // ensure that toggling still works if you click the button
          onStateChange: ({ isOpen: newState }) => setIsOpen(newState),
        }}
      />
    </div>
  );
}

render(<App />, document.getElementById('root'));
